#!/usr/bin/env node
import { dirname, join } from "node:path";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { spawn, spawnSync } from "node:child_process";

const args = process.argv.slice(2);
const command = args[0];
const cwd = process.cwd();
const marker = join(cwd, ".teamai-e2e-initialized");
const slowMarker = join(cwd, ".teamai-e2e-slow");
const childPidMarker = join(cwd, ".teamai-e2e-child-pid");
const passwordMarker = join(cwd, ".teamai-e2e-expected-password");
const changedHostMarker = join(cwd, ".teamai-e2e-host-changed");

function requestPassword() {
  const helper = process.env.SSH_ASKPASS;
  if (!helper || !process.env.TEAMAI_ASKPASS_PIPE) return "";
  const script = join(dirname(helper), "teamai-askpass.ps1");
  const result = spawnSync("powershell.exe", ["-NoLogo", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-File", script, "Password:"], {
    encoding: "utf8",
    env: process.env,
    windowsHide: true,
  });
  return result.status === 0 ? result.stdout : "";
}

function requirePasswordIfConfigured() {
  if (!existsSync(passwordMarker)) return true;
  if (existsSync(changedHostMarker) && readFileSync(changedHostMarker, "utf8") === "changed") {
    console.error("REMOTE HOST IDENTIFICATION HAS CHANGED!");
    return false;
  }
  const expected = readFileSync(passwordMarker, "utf8");
  const first = requestPassword();
  const second = requestPassword();
  if (first !== expected || second !== expected) {
    console.error("git@example.test: Permission denied (password).");
    return false;
  }
  return true;
}

if (args.includes("--version")) {
  console.log("0.21.0");
  process.exit(0);
}

if (command === "status") {
  if (!existsSync(marker)) {
    console.error("Not initialized. Run teamai init first.");
    process.exit(1);
  }
  if (!requirePasswordIfConfigured()) process.exit(1);
  console.log("\u001b[32mTeamAI ready\u001b[0m · scope: project");
  process.exit(0);
}

if (command === "init") {
  if (args[1]?.startsWith("git@") || args[1]?.startsWith("ssh://")) {
    if (!requirePasswordIfConfigured()) process.exit(1);
  }
  writeFileSync(marker, JSON.stringify({
    args,
    cwd,
    hasAskpassPipe: Boolean(process.env.TEAMAI_ASKPASS_PIPE),
    gitSshCommand: process.env.GIT_SSH_COMMAND ?? null,
  }, null, 2));
  console.log(`Initialized ${args[1]} in ${cwd}`);
  process.exit(0);
}

if (command === "pull") {
  if (!requirePasswordIfConfigured()) process.exit(1);
  if (existsSync(slowMarker)) {
    const child = spawn(process.execPath, ["-e", "setInterval(() => {}, 1000)"], { stdio: "ignore" });
    writeFileSync(childPidMarker, String(child.pid));
    let index = 0;
    setInterval(() => console.log(`long pull tick ${++index}`), 250);
  } else {
    console.log("Pulling team resources…");
    console.error("diagnostic stream check");
    setTimeout(() => { console.log("Pull complete"); process.exit(0); }, 250);
  }
} else if (command === "push") {
  if (!requirePasswordIfConfigured()) process.exit(1);
  if (!args.includes("--all")) {
    console.error("push must include --all");
    process.exit(2);
  }
  console.log(`Push complete with args: ${args.join(" ")}`);
  process.exit(0);
} else {
  console.error(`Unsupported E2E command: ${command ?? "none"}`);
  process.exit(2);
}
